cases.script:
printf '%s\n' \
  '10 1 8:1 / / rw,relatime - ext4 /dev/vda1 rw,errors=remount-ro' \
  '11 10 0:41 / /mnt/cache rw,nosuid,nodev shared:1 master:2 - tmpfs tmpfs rw,size=65536k' \
  '12 10 8:2 / /srv/data ro,noexec - ext4 /dev/vdb1 ro' \
  > mountinfo
run_case() {
  if [[ $(type -t bashmount) == builtin ]]; then
    bashmount --findmnt-table mountinfo
    return $?
  fi

  local rows id parent dev root target opts fstype source
  rows=$(findmnt --tab-file mountinfo --raw --noheadings -o ID,PARENT,MAJ:MIN,FSROOT,TARGET,VFS-OPTIONS,FSTYPE,SOURCE)
  while IFS=$' \t' read -r id parent dev root target opts fstype source; do
    [[ -n $id ]] || continue
    # findmnt --raw spells an encoded space as \x20; the builtin decodes
    # mountinfo's kernel octal escape to a literal space.
    id=${id//\\x20/ }
    parent=${parent//\\x20/ }
    dev=${dev//\\x20/ }
    root=${root//\\x20/ }
    target=${target//\\x20/ }
    opts=${opts//\\x20/ }
    fstype=${fstype//\\x20/ }
    source=${source//\\x20/ }
    printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' \
      "$id" "$parent" "$dev" "$root" "$target" "$opts" "$fstype" "$source"
  done <<< "$rows"
}
run_case

